-- Phase 13 Direct Store Coupon Recognition (record-only)
create table if not exists public.fr_direct_store_coupon_claims (
 id uuid primary key default gen_random_uuid(),order_id uuid not null references public.shop_orders(id) on delete cascade,customer_id uuid not null references public.profiles(id) on delete cascade,shop_id uuid not null references public.profiles(id) on delete cascade,coupon_code text not null,transaction_reference text,customer_note text,status text not null default 'pending' check(status in ('pending','recognized','rejected')),reviewer_id uuid references public.profiles(id),review_note text,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(order_id));
alter table public.fr_direct_store_coupon_claims enable row level security;
drop policy if exists fr_direct_coupon_owner_read on public.fr_direct_store_coupon_claims;
create policy fr_direct_coupon_owner_read on public.fr_direct_store_coupon_claims for select to authenticated using(customer_id=auth.uid() or shop_id=auth.uid() or public.is_friend_ride_admin());
create or replace function public.fr_direct_store_coupon_submit(p_order_id uuid,p_coupon_code text,p_transaction_reference text default null,p_customer_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid();v_order public.shop_orders%rowtype;v_claim uuid;v_role text;begin if v_uid is null then raise exception 'Authentication required';end if;select role into v_role from public.profiles where id=v_uid;if lower(coalesce(v_role,''))<>'customer' then raise exception 'Customer only';end if;if length(trim(coalesce(p_coupon_code,'')))<2 or length(trim(p_coupon_code))>80 then raise exception 'Coupon code required (2-80 chars)';end if;select * into v_order from public.shop_orders where id=p_order_id for update;if not found then return jsonb_build_object('ok',false,'reason','order_not_found');end if;if v_order.customer_id<>v_uid then raise exception 'Order ownership check failed';end if;insert into public.fr_direct_store_coupon_claims(order_id,customer_id,shop_id,coupon_code,transaction_reference,customer_note) values(v_order.id,v_uid,v_order.shop_id,trim(p_coupon_code),nullif(trim(coalesce(p_transaction_reference,'')),''),nullif(trim(coalesce(p_customer_note,'')),'')) on conflict(order_id) do update set coupon_code=excluded.coupon_code,transaction_reference=excluded.transaction_reference,customer_note=excluded.customer_note,status='pending',reviewer_id=null,review_note=null,reviewed_at=null,updated_at=now() returning id into v_claim;return jsonb_build_object('ok',true,'claim_id',v_claim,'status','pending','message','Submitted for store/admin recognition; order payment status is unchanged.');end;$$;
create or replace function public.fr_direct_store_coupon_review(p_claim_id uuid,p_decision text,p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid();v_claim public.fr_direct_store_coupon_claims%rowtype;v_role text;begin if v_uid is null then raise exception 'Authentication required';end if;if p_decision not in ('recognize','reject') then raise exception 'Decision must be recognize or reject';end if;select * into v_claim from public.fr_direct_store_coupon_claims where id=p_claim_id for update;if not found then return jsonb_build_object('ok',false,'reason','claim_not_found');end if;select role into v_role from public.profiles where id=v_uid;if not public.is_friend_ride_admin() and (v_claim.shop_id<>v_uid or lower(coalesce(v_role,'')) not in ('partner','shop_partner','store_partner')) then raise exception 'Shop owner or Admin only';end if;if v_claim.status<>'pending' then return jsonb_build_object('ok',false,'reason','already_reviewed');end if;update public.fr_direct_store_coupon_claims set status=case when p_decision='recognize' then 'recognized' else 'rejected' end,reviewer_id=v_uid,review_note=p_note,reviewed_at=now(),updated_at=now() where id=p_claim_id;return jsonb_build_object('ok',true,'decision',p_decision,'order_payment_status_unchanged',true);end;$$;
revoke all on function public.fr_direct_store_coupon_submit(uuid,text,text,text) from public,anon;revoke all on function public.fr_direct_store_coupon_review(uuid,text,text) from public,anon;grant execute on function public.fr_direct_store_coupon_submit(uuid,text,text,text) to authenticated;grant execute on function public.fr_direct_store_coupon_review(uuid,text,text) to authenticated;